// CREDENTIAL INVENTORY (rc-8.5.21-c, 2026-10-16) — every script / test / package.json entry that
// derives (or derived) database or service credentials, its class, and the scan rules it is still
// allowed. Generated from the scan at the freeze and then hand-checked; rendered in
// docs/CREDENTIAL-SAFETY.md (node scripts/db/scan-credential-derivation.mjs --inventory-md).
//
//   cls     readonly = read-only diagnostic · write = writes production · local = local-only
//   status  'migrated: loader' — uses scripts/lib/prod-db-credentials.mjs; nothing allowlisted
//           'migrated: loader (gated write)' — writes only through --prod-write + TTY
//           'partially migrated…' — DB access migrated, a residual rule is still allowlisted
//           'legacy: allowlisted pending migration' — unchanged; allowlisted until migrated
//           'allowlisted: no DB credential derived' — names a pattern but derives no DB credential
//   allow   scan rules this entry may still trigger. Every (path, rule) pair must be in the
//           FROZEN baseline (credential-derivation.frozen.txt): entries may be removed or
//           narrowed, never added. A new script uses the loader instead.

export const CLASSES = Object.freeze({ readonly: 'read-only diagnostic', write: 'writes production', local: 'local-only' })

const E = (path, cls, status, allow, note, purpose = null) => Object.freeze({ path, cls, status, allow: Object.freeze(allow), note, ...(purpose ? { purpose } : {}) })

